`816-844`: **Consider error handling improvements for LTI reference migration**

The LTI reference migration logic correctly handles the pattern matching and replacement, but could benefit from more robust error handling and validation.



Consider these improvements:
1. Validate that the LTI content exists before attempting to copy
2. Handle potential null returns from `copyLTIContent` more gracefully
3. Add specific logging for skipped references when copy fails

```diff
 Pattern idPattern = Pattern.compile("(https?://[^/]+/access/(?:basic)?lti/site)/" + Pattern.quote(oldSiteId) + "/content:([0-9]+)");
 Matcher matcher = idPattern.matcher(html);
 StringBuffer sb = new StringBuffer();
 boolean foundLtiLink = false;
 while(matcher.find()) {
 	String urlFirstPart = matcher.group(1);
 	Long ltiContentId = Long.valueOf(matcher.group(2));
-	log.info("Updating reference: {}", matcher.group(0));
+	log.debug("Updating reference: {}", matcher.group(0));
 	foundLtiLink = true;
+	String updatedReference = matcher.group(0); // Default to original if copy fails
 	try {
 		Map<String, Object> ltiContent = ltiService.getContentDao(ltiContentId, oldSiteId, securityService.isSuperUser());
-		String newSakaiId = copyLTIContent(ltiContent, siteId, oldSiteId);
-		if ( newSakaiId != null ) sakaiId = newSakaiId;
-		String[] bltiId = sakaiId.split("/");
-		ltiContentId = Long.valueOf(bltiId[2]);
+		if (ltiContent != null) {
+			String newSakaiId = copyLTIContent(ltiContent, siteId, oldSiteId);
+			if (newSakaiId != null) {
+				sakaiId = newSakaiId;
+				String[] bltiId = sakaiId.split("/");
+				if (bltiId.length > 2) {
+					ltiContentId = Long.valueOf(bltiId[2]);
+					updatedReference = urlFirstPart + "/" + siteId + "/content:" + ltiContentId;
+					log.debug("New reference: {}", updatedReference);
+				} else {
+					log.warn("Invalid sakaiId format after copy: {}", newSakaiId);
+				}
+			} else {
+				log.warn("Failed to copy LTI content {}, keeping original reference", ltiContentId);
+			}
+		} else {
+			log.warn("LTI content {} not found in site {}", ltiContentId, oldSiteId);
+		}
 	} catch (Exception e) {
-		log.warn("Unable to import LTI tool to new site: {}", e);
-	} finally {
-		String updatedReference = urlFirstPart + "/" + siteId + "/content:" + ltiContentId;
-		log.info("New reference: {}", updatedReference);
-		matcher.appendReplacement(sb, Matcher.quoteReplacement(updatedReference));
+		log.warn("Unable to import LTI tool {} to new site: {}", ltiContentId, e.toString());
 	}
+	matcher.appendReplacement(sb, Matcher.quoteReplacement(updatedReference));
 }

 if(foundLtiLink) {
 	matcher.appendTail(sb);
 	explanation = sb.toString();
-	log.info("Updated at least one LTI reference lesson HTML");
+	log.debug("Updated at least one LTI reference in lesson HTML");
 }
```

