+            bySite.put(ps.getSiteId(), ps);
+        }
+
+        // Mark previously pinned-but-no-longer-present as unpinned
+        for (PinnedSite ps : existing) {
+            if (!Boolean.TRUE.equals(ps.getHasBeenUnpinned()) && !ordered.contains(ps.getSiteId())) {
+                ps.setHasBeenUnpinned(true);
+                pinnedSiteRepository.save(ps);
+            }
+        }
+
+        // Apply the new order; ensure these entries are pinned
+        for (int i = 0; i < ordered.size(); i++) {
+            String sid = ordered.get(i);
+            PinnedSite ps = bySite.get(sid);
+            if (ps == null) {
+                ps = new PinnedSite(userId, sid);
+            }
+            ps.setHasBeenUnpinned(false);
+            ps.setPosition(i);
+            pinnedSiteRepository.save(ps);
+        }
