```java
private void importCanvasSyllabus(Element resourceXml, Element itemXml, CartridgeLoader loader) {
    if (syllabusManager == null) return;
    String syllabusTitle = itemXml != null ? itemXml.getChildText(CC_ITEM_TITLE, ns.getNs()) : null;
    if (StringUtils.isBlank(syllabusTitle)) syllabusTitle = "Canvas Syllabus";

    String syllabusContent = "";
    for (Element file : resourceXml.getChildren(FILE, ns.getNs())) {
        String fileHref = file.getAttributeValue(HREF);
        if (fileHref != null && fileHref.endsWith(".html")) {
            try (InputStream htmlStream = loader.getFile(fileHref)) {
                if (htmlStream != null) {
                    syllabusContent = new String(htmlStream.readAllBytes(), StandardCharsets.UTF_8);
                }
            } catch (Exception e) {
                log.warn("Failed to load Canvas syllabus HTML: {}", fileHref, e);
            }
            break;
        }
    }
    if (StringUtils.isBlank(syllabusContent)) {
        log.warn("Canvas syllabus resource {} contained no HTML file; skipping syllabus creation.", resourceXml.getAttributeValue(IDENTIFIER));
        return;
    }
    String body = ComponentManager.get(FormattedText.class).getHtmlBody(syllabusContent);
    syllabusContent = fixupInlineReferences(body);

    SyllabusItem syllabusItem = syllabusManager.getSyllabusItemByContextId(siteId);
    if (syllabusItem == null) {
        syllabusItem = syllabusManager.createSyllabusItem(simplePageBean.getCurrentUserId(), siteId, null);
    }
    int position = syllabusManager.findLargestSyllabusPosition(syllabusItem) + 1;
    syllabusManager.createSyllabusDataObject(syllabusTitle, position, syllabusContent, "yes",
        SyllabusData.ITEM_POSTED, "none", null, null, false, null, null, syllabusItem);
    log.debug("Created Canvas syllabus entry: {}", syllabusTitle);
}
```

