```java
private String visibilityChoiceFor(SimplePage page) {
    if (page == null) return VIS_VISIBLE;
    if (page.isHidden()) return VIS_HIDE;
    if (page.isHiddenFromNavigation()) return VIS_HIDE_FROM_NAV;
    return VIS_VISIBLE;
}

private void applyVisibilityChoice(String choice) {
    String normalized = (choice == null ? VIS_VISIBLE : choice);
    this.hidePage = VIS_HIDE.equals(normalized);
    this.hidePageFromNavigation = VIS_HIDE_FROM_NAV.equals(normalized);
}
```


