+        final boolean hasExtendedTimes = publishedAssessmentSettings.getExtendedTimesSize() != 0 && extendedTimes != null;
+
+        if (!baseStart.isAfter(now)) { // now or past
+            eventTrackingService.post(eventTrackingService.newEvent(
+                SamigoConstants.EVENT_ASSESSMENT_UPDATE_AVAILABLE, ref, true, notiMask));
+            if (hasExtendedTimes) {
+                for (ExtendedTime exTime : extendedTimes) {
+                    Instant startInstant = (exTime.getStartDate() != null) ? exTime.getStartDate().toInstant() : null;
+                    if (startInstant != null && startInstant.isAfter(now)) {
+                        eventTrackingService.delay(eventTrackingService.newEvent(
+                            SamigoConstants.EVENT_ASSESSMENT_AVAILABLE, ref, true, notiMask), startInstant);
+                    }
+                }
+            }
+        } else {
+            eventTrackingService.delay(eventTrackingService.newEvent(
+                SamigoConstants.EVENT_ASSESSMENT_AVAILABLE, ref, true, notiMask), baseStart);
+            if (hasExtendedTimes) {
+                boolean postedUpdate = false;
+                for (ExtendedTime exTime : extendedTimes) {
+                    Instant startInstant = (exTime.getStartDate() != null) ? exTime.getStartDate().toInstant() : null;
+                    if (startInstant == null) continue;
+                    if (startInstant.isBefore(now) && !postedUpdate) {
+                        eventTrackingService.post(eventTrackingService.newEvent(
+                            SamigoConstants.EVENT_ASSESSMENT_UPDATE_AVAILABLE, ref, true, notiMask));
+                        postedUpdate = true;
+                    } else if (startInstant.isAfter(now) && !baseStart.equals(startInstant)) {
+                        eventTrackingService.delay(eventTrackingService.newEvent(
+                            SamigoConstants.EVENT_ASSESSMENT_AVAILABLE, ref, true, notiMask), startInstant);
+                    }
+                }
+            }
+        }
+    }
