> +	private static final DateTimeFormatter DATETIME_FORMATTER = DateTimeFormatter.ofPattern("MM/dd/yy h:mm a");
> +	private static final DateTimeFormatter DATE_FORMATTER = DateTimeFormatter.ofPattern("MM/dd/yy");
>  
>  	public static String format_h_mm_a(Date date) {
>  		if (date == null)
>  			return "";
> -		dateFormat.applyPattern("h:mm a");
> -		return dateFormat.format(date);
> +		LocalDateTime ldt = LocalDateTime.ofInstant(Instant.ofEpochMilli(date.getTime()), ZoneId.systemDefault());
> +		return TIME_FORMATTER.format(ldt);
>  	}
>  
>  	public static String format_date_h_mm_a(Date date) {
>  		if (date == null)
>  			return "";
> -		dateFormat.applyPattern("MM/dd/yy h:mm a");
