> @@
> -            schedulingService().scheduleWithFixedDelay(
> +            refreshAuthzGroupTask = schedulingService().scheduleWithFixedDelay(
>                  new RefreshAuthzGroupTask(),
>                  120, // minimally wait 2 mins for sakai to start
>                  refreshTaskInterval, // delay before running again
>                  TimeUnit.SECONDS
>              );
> @@
>  	public void destroy()
>  	{
> +        if (refreshAuthzGroupTask != null) {
> +            refreshAuthzGroupTask.cancel(true);
> +            refreshAuthzGroupTask = null;
> +        }
> +
