```java
private void updateGradebookAssociation(SessionState state,
                                        String siteId,
                                        String assignmentRef,
                                        String associateGradebookAssignment,
                                        String submissionId,
                                        String action) {
    if (!gradingService.isGradebookGroupEnabled(siteId)) {
        addAlerts(state, assignmentToolUtils.integrateGradebook(stateToMap(state), siteId, assignmentRef,
                associateGradebookAssignment, null, null, -1, null, submissionId, action, -1));
        return;
    }
    List<String> gradebookUids = gradingService.getGradebookUidByExternalId(associateGradebookAssignment);
    for (String gradebookUid : gradebookUids) {
        addAlerts(state, assignmentToolUtils.integrateGradebook(stateToMap(state), gradebookUid, assignmentRef,
                associateGradebookAssignment, null, null, -1, null, submissionId, action, -1));
    }
}
```
